#!/usr/bin/env python3
"""Write STR reference sequences to a FASTA file."""

import argparse

STR_ENTRIES = [
    ("STR_3N",
        ""
     ),
    ("STR4",
        ""
     ),
    ("STR5",
        ""
     ),
    ("STR7",
        ""
     ),
    ("STR12",
        ""
     ),
    ("STR25",
        ""
     ),
    ("STR27",
        ""
     ),
    ("STR28",
        ""
     ),
    ("STR29",
        ""
     ),
    ("STR33",
        ""
     ),
    ("STR38",
        ""
     ),
]


def write_fasta(entries, output_path):
    with open(output_path, "w") as fh:
        for name, seq in entries:
            fh.write(f">{name}\n")
            fh.write(seq.upper() + "\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Write STR reference sequences to a FASTA file."
    )
    parser.add_argument(
        "-o",
        "--output",
        default="str_sequences.fasta",
        help="Output FASTA file path (default: str_sequences.fasta)",
    )
    args = parser.parse_args()

    print(f"Writing {len(STR_ENTRIES)} STR sequences to {args.output} ...")
    write_fasta(STR_ENTRIES, args.output)
    total_bp = sum(len(seq) for _, seq in STR_ENTRIES)
    avg_len = total_bp / len(STR_ENTRIES)
    print(
        f"Done: {len(STR_ENTRIES)} entries, "
        f"{total_bp} total bp (avg {avg_len:.0f} bp/entry)."
    )
